def check_symmetric_case(a):
    # Equation: a^6 = 1006*a^2 + 2012
    LHS = a**6
    RHS = 1006 * (a**2) + 2012
    return LHS, RHS

results = {}
for a in range(1, 7):
    lhs, rhs = check_symmetric_case(a)
    results[a] = (lhs, rhs)
    print(f"a={a}: LHS={lhs}, RHS={rhs}, Match={lhs == rhs}")

